#! btw 1
#! name: hand-dubstep-140-v2
#! license: CC0-1.0
#! visibility: public
# hand-dubstep-140 v2: a whole track in one program.
# intro 8 · build 8 (the riser lands on the phrase line) · drop 16 · breakdown 8 · drop 2 16 · outro 8
tempo 140
key fm

# the parts, named once
let kicks = x ~ ~ ~ ~ ~ ~ ~ ~ ~ x ~ ~ ~ ~ ~
let snares = ~ ~ ~ ~ ~ ~ ~ ~ x ~ ~ ~ ~ ~ ~ ~
let hats = ~ ~ x ~ ~ ~ x ~ ~ ~ x ~ ~ x x ~
let wob_a = f1 ~ ~ f1 ~ ~ ab1 ~ f1 ~ ~ ~ eb1 ~ c1 ~
let wob_b = f1 ~ f1 ~ ~ ~ db1 ~ ~ ~ c1 ~ eb1 ~ eb1 ~
let lead_a = ~ ~ c4 ~ ab3 ~ ~ ~ f3 ~ ~ g3 ~ ab3 ~ ~
let lead_b = ~ ~ c4 ~ eb4 ~ ~ ~ db4 ~ c4 ~ ab3 ~ ~ ~
let changes = <chord(fm) chord(fm) chord(db) chord(db) chord(ab) chord(ab) chord(eb) chord(eb)>

# the drop's groove: the drums and the wobble bass on one deck, and a filter that opens and
# shuts once a bar (the wub), for as many bars as it is told
def groove(deck, bars) {
  deck $deck: kick kicks | snare snares | hihat hats | bass <wob_a wob_b> inst=wobble-lead
  repeat $bars every 1 bars {
    master: filter lp 300 -> 2800 over 1 bars
  }
}

section intro 8 bars {
  deck A: kick kicks | hihat hats vel=50..80
  deck B: harmony changes inst=warm-pad
  master: filter lp 400 -> 6000 over 8 bars
}

section build 8 bars {
  deck A: kick kicks | snare snares | hihat x*8 vel=50..100
  deck B: harmony changes inst=warm-pad | melody <lead_a lead_b> inst=pwm-lead
  # the riser: it opens over all eight bars and ends on the phrase line, where the drop starts
  master: filter hp 100 -> 5000 over 8 bars
  master: reverb 0.1 -> 0.5 over 8 bars
  # and the roll leads into it
  before drop 4 bars: move loop_roll on A over 4 bars
}

section drop 16 bars {
  master: filter off
  master: reverb 0.15
  groove(A, 16)
  deck B: melody <lead_a lead_b> inst=pwm-lead | harmony changes inst=warm-pad
}

section breakdown 8 bars {
  deck A: hihat x ~ x ~ vel=40..60
  deck B: harmony changes inst=warm-pad | melody <lead_a lead_b> inst=pwm-lead
  master: filter lp 6000 -> 1200 over 8 bars
  master: reverb 0.45
}

section drop2 16 bars {
  master: filter off
  master: reverb 0.15
  groove(A, 16)
  deck B: melody <lead_b lead_a> inst=pwm-lead | harmony changes inst=warm-pad
}

section outro 8 bars {
  deck A: kick kicks | hihat hats vel=40..70
  deck B: harmony changes inst=warm-pad
  master: filter lp 8000 -> 500 over 8 bars
}

arrange intro build drop breakdown drop2 outro
end after outro

# F10, composition made literal: stack(a, b) plays sections at once, then(a, b) one after the other,
# `arrange a b c` is then(a, b, c), `silence` is the unit of both, and a `let` names a composition.
# Original, CC0-1.0.
tempo 118
key am

section intro 4 bars {
  deck A: hihat x ~ x ~ vel=50..80
}

section groove 8 bars {
  deck A: kick x ~ x ~ | snare ~ x ~ x | hihat x*8 vel=60..90
}

section wash 8 bars {
  deck B: harmony <chord(am) chord(f) chord(c) chord(g)>
}

# four bars: stacked on an eight-bar section it stops where it ends (its decks stop), and played twice
# in a row (then) it fills the eight
section riff 4 bars {
  deck B: melody <a4 c5 e5 g5> | bass <a1 ~ c2 ~>
}

section coda 4 bars {
  deck A: kick x ~ ~ ~
  deck B: harmony chord(am)
}

# an alias: a name for two sections together
let verse = stack(groove, wash)

# intro, then the verse with the riff twice over it, then the coda; the order inside stack() does not matter
arrange intro stack(then(riff, riff), verse) coda
end after coda

#! btw 1
#! name: arrange-every-n
#! license: CC0-1.0
#! visibility: public
# arrange-every-n: a change that comes round only every Nth pass of a looping arrange.
# A count right after the mark says how often (`~3`: the 3rd pass, the 6th ...); no count is every pass. Six passes, then an outro.
tempo 124
key am
let riff = a3 c4 e4 g4 a4 g4 e4 c4
let bass_a = a1 ~ a1 ~ c2 ~ a1 e2
let bass_b = a2 ~ e3 ~ c3 ~ ~ e3
let kik = x ~ x ~
let hats = ~ x ~ x ~ x ~ x
section groove 4 bars {
  deck A: kick kik | hihat hats
  deck B: bass bass_a inst=fm-bass | arp riff
}
section lift 4 bars {
  deck A: kick kik | snare ~ x ~ x | hihat hats
  deck B: bass bass_b inst=fm-bass | arp riff
}
section outro 4 bars {
  deck A: kick kik
}
arrange {
  groove lift
  ~3 riff rev                  # passes 3 and 6: the arp turns round, and turns back
  groove
  ~2 bass_* drift 0.2          # passes 2, 4 and 6: both basses wander a step, and stay there
  @4 kik double                # pass 4 only: the next section's kick doubles, then goes back
  lift
} loop 6 then outro end

#! btw 1
#! name: arrange-jux
#! license: CC0-1.0
#! visibility: public
# arrange-jux: a pattern keeps its left copy and plays a mutated copy on the right. Best on headphones.
# `~ riff jux rev` is Tidal's `jux rev`: the arp stays where it was and a reversed copy plays hard right.
# What comes before `jux` in a chain works on both copies, what comes after on the right copy only.
tempo 124
key am
let pulse = a2 ~ a2 ~ a2 ~ e2 ~
let riff = a3 c4 e4 a4 e4 c4 e4 c4
let hook = a4 ~ ~ c5 ~ e5 ~ ~
let hats = ~ x ~ x ~ x ~ x
section intro 4 bars {
  deck A: kick x ~ x ~ | hihat hats
  deck B: bass pulse inst=fm-bass
}
section groove 8 bars {
  deck A: kick x ~ x ~ | snare ~ x ~ x | hihat hats
  deck B: bass pulse inst=fm-bass | arp riff
}
section peak 8 bars {
  deck A: kick x ~ x ~ | snare ~ x ~ x | hihat hats
  deck B: bass pulse inst=fm-bass | arp riff | melody hook
}
section outro 4 bars {
  deck A: kick x ~ ~ ~
  deck B: arp riff
}
arrange {
  intro groove
  ~ riff jux rev
  groove
  ~ hook rot 1 | jux rev | up 2
  peak
  ~ riff jux rot 3 | thin 0.2
  peak
} loop 2 then outro end

#! btw 1
#! name: arrange-mutations
#! license: CC0-1.0
#! visibility: public
# arrange-mutations: an arrangement that rewrites its own patterns as it goes.
# `~` changes a pattern from there on, `@` for the next section only; four passes, each a new generation, then an outro.
tempo 132
key am
let acid_a = a1! ~ a1 ~ c2^ ~ a1 e2 ~ a1 ~ ~ g1 ~ a1 ~
let acid_b = a2 ~ ~ c3 ~ ~ e3 ~
let hoov = a3 ~ c4 ~ e4 ~ ~ ~
let hats = ~ x ~ x ~ x ~ x
section intro 4 bars {
  deck A: kick x ~ x ~ | hihat hats
}
section build 4 bars {
  deck A: kick x ~ x ~ | hihat hats
  deck B: bass acid_a inst=fm-bass
}
section drop 8 bars {
  deck A: kick x ~ x ~ | snare ~ x ~ x | hihat hats
  deck B: bass acid_a inst=fm-bass | melody hoov | arp acid_b
}
section outro 4 bars {
  deck A: kick x ~ ~ ~
  deck B: melody hoov
}
arrange {
  intro build drop
  ~ acid_a rot 2 | accent 0.2, hoov up 2
  drop
  ~ acid_* drift 0.15
  @ hoov rev
  drop
  ~ hats thin 0.25 | fill 0.3
} loop 4 then outro end

#! btw 1
#! name: the Assyrian, 122
#! license: CC0-1.0
#! visibility: public
# assyrian-122: the same deep house over an anapestic line (CC0-1.0; the words are Byron's, Hebrew Melodies, 1815, in the public
# domain). "The Assyrian came down like the wolf on the fold" is twelve syllables, two weak and a strong, four times. The book says
# its feel is triplet, so the voice and the shaker go in a cycle of twelve sixteenths, a 6/8 bar of three syllables to the beat
# against the four-on-the-floor kick, and come round together every three bars. The sections are twelve bars. Four passes, about
# six minutes.
arrange from template(deep-house, @byron_assyrian_wolf)

#! btw 1
#! name: a commit message, 122
#! license: CC0-1.0
#! visibility: public
# commit-message-122: any words are a phrase (CC0-1.0, original). A commit message has no curated scansion, so its stress is worked
# out: the small words (the, and) are weak and the first syllable of every other word is strong, which here gives nine syllables
# with the stress on make, drop, deeper, move and kick. They are accented and sit on the beats; the weak ones fall between. It
# is a two-bar line in the straight feel, sung four times in each eight-bar section. `check` says what the phrase gave.
arrange from template(deep-house, "make the drop deeper and move the kick")

#! genre: https://ontology.bitwrap.io/genre/techno
#! tags: acid, supersaw, four on floor, drop
# linked.btw: a program that says what it is. The two lines above are header lines: comments to the language, so
# this runs anywhere and its CID is the same with or without them. A host that has the bitwrap ontology
# (https://ontology.bitwrap.io/ns#) reads them: `genre` is one genre (an IRI, or `techno`, `genre:techno`, `bw:Techno`),
# `tags` are terms of the vocabulary by local name, label or IRI (an instrument, a groove, a section ...). A misspelt
# one is a warning in `btw check` ("unknown tag `acidd`: did you mean `acid`?") and an error when it is saved.
# `btw jsonld` turns the program into linked data: its genre and tags, key, tempo, sections, licence, and the Euclidean
# rhythms below linked to the ontology's Euclidean rhythm class (e(4,16) is the shape of techno's own kick).
tempo 128
key am

section intro 8 bars {
  deck A: kick e(4,16) | hihat e(5,8)
}

section drop 16 bars {
  deck A: kick e(4,16) | snare e(2,16,4) | hihat e(5,8)
  deck B: bass <a1 ~ c2 ~> | harmony chord(am)
}

arrange intro drop

# multi-arrange: three named arrangements. `open` plays once and goes to `set`, which loops its drop twice and falls
# through to `close`.
tempo 124
key am

let kk = x ~ ~ ~ x ~ ~ ~ x ~ ~ ~ x ~ ~ ~
let hh = ~ ~ x ~ ~ ~ x ~ ~ ~ x ~ ~ ~ x ~
let riff = a2 ~ a2 a2 ~ c3 ~ a2 e2 ~ e2 g2 ~ e2 ~ e2

section intro 2 bars {
  deck A: kick kk
}
section build 2 bars {
  deck A: kick kk | hihat hh
}
section drop 4 bars {
  deck A: kick kk | hihat hh | bass riff inst=sub-bass
}
section outro 2 bars {
  deck A: kick kk
}

arrange open: intro build then set
arrange set: drop loop 2
arrange close: outro end
start open

# named-arrange-mutations: named arrangements with an `arrange { }` mutation inside one of them. `open` plays the drop as
# written, `set` rotates the acid line between its two drops (twice through), and `close` plays the drop as written again.
tempo 128
key am

let kik = x ~ ~ ~ x ~ ~ ~ x ~ ~ ~ x ~ ~ ~
let acid = a2 ~ c3 e3 ~ a2 g2 ~ a2 a2 ~ e3 ~ c3 ~ g2

section intro 2 bars {
  deck A: kick kik
}
section drop 2 bars {
  deck A: kick kik | bass acid inst=sub-bass
}
section outro 2 bars {
  deck A: kick kik
}

arrange open: intro drop then set
arrange set: {
  drop
  ~ acid rot 2
  drop
} loop 2
arrange close: drop outro end

#! btw 1
#! name: lanternfall
#! license: CC0-1.0
#! visibility: public
#! author: Claude Sonnet 5.5
#! genre: edm
#! tags: synthwave, synthwave-1, edm-standard-1, four-on-floor, sidechained, warm-pad, sub-bass, pluck, fm-bell, euclidean-rhythm, ghost-note, buildup, drop, breakdown
# lanternfall: a two minute track in one program (original, CC0-1.0). See docs/btw/showcase.md for which feature is where.
#
#   intro 8 . build 8 . drop 16 . breakdown 4 + 4 . second drop 16, a tone higher . outro 8      (64 bars, about two minutes)
#
# What the offline render (`djctl btw render`) plays is the notes, the sections, the tempo curve, `duck` and `mix`, so the arc
# of the track is in the mixes: each section sets its own, and the crescendo of the build and the fade of the outro are
# stepped mixes (a `repeat` with `$i`). The lines marked (live) are what the render does not play: filters and reverbs, the sung
# lines, the performed inputs, and the level ramps and lfos (a render that carries those hears them as a fade-in, a swell and a
# breath; each one starts where the mix of its section already holds the knob, so the two agree).
let base = 122                       # the tempo the build starts from; every other tempo is written from it
let drop_len = 16
let half = drop_len / 2

tempo base - 8
key am

# ---- the changes, written once: a def with ports, wired below to the pad, the pluck and the bass ------------------
def changes() out: chords {
  emit <i VI III VII>                # Am F C G, a bar each
}

# the pad plays the changes voice-led, and hands the roots on as a bass line
def bed(oct) in: chords out: bass {
  deck B: harmony $chords voice-lead inst=warm-pad oct=$oct len=16 vel=55..75
  emit [$chords]
}

# the pluck arpeggiates the changes: 4 notes a bar, 8 or 16 (the chord is repeated to give it more steps)
def sparkle(steps) in: chords {
  deck B: arp $chords inst=pluck vel=45..70 when $steps == 4
  deck B: arp [$chords $chords] inst=pluck vel=45..70 when $steps == 8
  deck B: arp [$chords $chords $chords $chords] inst=pluck vel=45..70 when $steps == 16
}

def sub_long() in: bass {
  deck A: bass $in inst=sub-bass oct=1 len=14 vel=80..90
}

# the offbeat eighths between the kicks
def sub_pulse() in: bass {
  deck A: bass [~ $in ~ $in ~ $in ~ $in] inst=sub-bass oct=1 len=2 vel=80..95
}

# the same, with a double-time pickup now and then (a chance: decided by a hash of the bar, so it is the same every run)
def sub_roll() in: bass {
  deck A: bass [~ $in ~ $in ~ $in ~ choose [$in [$in $in]] weights 3 1 seed=5] inst=sub-bass oct=1 len=2 vel=80..95
}

wire changes.out -> bed.chords
wire changes.out -> sparkle.chords
wire bed.out -> sub_long.in
wire bed.out -> sub_pulse.in
wire bed.out -> sub_roll.in

# ---- the drums ----------------------------------------------------------------------------------------------------
let tick = ~ x?0.35 x x?0.35         # a beat of hats: the offbeat sixteenth is sure, the ones round it are ghosts
let busy = x?0.5 x?0.4 x x?0.4
let four = e(4,16)                   # four on the floor: the ontology names it
let backbeat = e(2,16,4)             # the snare on two and four
let fill = ~ ~ ~ ~ x ~ ~ ~ x x x x x x x x   # a half bar of sixteenths: the fill at the end of every fourth bar

def drumline(n) {
  deck A: kick e(4,16) vel=100..115
  deck A: snare <backbeat backbeat backbeat fill> vel=90..105
  deck A: hihat tick tick tick tick vel=45..80 when $n < 3
  deck A: hihat busy busy busy busy vel=45..85 when $n >= 3
  deck A: clap e(3,8) vel=70..90 when $n >= 3
}

# ---- the hook: degrees of the key, so the second drop plays it a tone up without a note changed -------------------
let q1 = deg(5 ~ 5 3 ~ 5 6 5)
let q2 = deg(6 ~ 6 1' ~ 3' 2' 1')
let q3 = deg(5 ~ 5 3 ~ 5 7 5)
let q4 = deg(7 ~ 2' 7 ~ 5 7 2')
let r1 = deg(4 #4 5 3 ~ 5 6 5)       # the answer starts with a chromatic step into the fifth
let r2 = deg(6 ~ 6 1' ~ 3' 4' 3')
let r3 = deg(7 ~ 5' 3' ~ 7 5 3)
let r4 = deg(2' ~ 7 5 ~ 3 5 7)

# two notes a bar, for the lines that are sung
let s1 = deg(5 ~ ~ ~ 3 ~ ~ ~)
let s2 = deg(1' ~ ~ ~ 6 ~ ~ ~)
let s3 = deg(5 ~ ~ ~ 7 ~ ~ ~)
let s4 = deg(2' ~ ~ ~ 7 ~ ~ ~)
let t1 = deg(3 ~ ~ ~ 5 ~ ~ ~)
let t2 = deg(6 ~ ~ ~ 1' ~ ~ ~)
let t3 = deg(5 ~ ~ ~ 3' ~ ~ ~)
let t4 = deg(7 ~ ~ ~ 2' ~ ~ ~)
let end_fall = deg(2' ~ ~ ~ 1, ~ ~ ~)       # the last bell tolls two octaves down, on the tonic

section intro 8 bars {
  tempo base - 8 -> base over 8 bars s-curve
  mix { A level 0.45, B level 0.3, master level 0.85 }         # the mix holds where the fade below starts
  deck B: level 0.3 -> 0.55 over 8 bars s-curve                # (live) the pad fades in
  deck A: hihat/12 x ~ x x ~ x vel=35..60                      # twelve steps against the bar: it comes round every three bars
  deck A: kick <~ ~ ~ ~ four four four four> vel=65..85
  bed(3)
  sparkle(4)
  master: filter lp 500 -> 9k over 8 bars exp                  # (live)
  master: reverb 0.45 -> 0.2 over 8 bars                       # (live)
}

section build 8 bars {
  tempo base -> base + 8 over 8 bars exp                       # the accelerando into the drop
  mix { master level 0.85 }
  repeat 4 every 2 bars {                                      # a crescendo in four steps: every copy is a mix held for two bars
    at bar 0 for 2 bars: mix { A level 0.45 + $i * 0.1, B level 0.55 + $i * 0.07 }
  }
  deck A: kick e(4,16) vel=90..110 | hihat x*8?0.8 vel=45..85 | snare <~ ~ ~ ~ ~ ~ x*8 x*16> vel=60..110
  sub_long()
  bed(3)
  sparkle(8)
  deck B: melody <~ ~ ~ ~ q1 q2 q3 q4> inst=pwm-lead vel=70..90   # the hook arrives in the last four bars
  duck B under A.kick 4db
  repeat 8 {                                                   # (live) a staircase, not a ramp: a bar at a time
    at bar $i: master: filter hp 100 + $i * $i * 60
    at bar $i: master: reverb 0.15 + 0.4 * $i / $n when $i % 2 == 1
  }
  before groove 2 beats: master: reverb 0.5 -> 0.9 over 2 beats   # (live)
  at bar 7 beat 3 for 1 beat: mix { A eq low -24, B eq low -24 }   # the breath: the bass drops out for the last beat
}

section groove drop_len bars {
  tempo base + 8
  mix {
    A level 0.9
    B level 0.85
    B eq low -6                                                # the pad gets out of the sub's way
    master level 0.85
  }
  drumline(2)
  sub_pulse()
  duck B under A.kick 6db attack=5ms release=120ms
  master: filter off                                           # (live) clears the build's high-pass
  master: reverb 0.15                                          # (live)
  master: level lfo sine 2 bars center=0.85 depth=0.03         # (live) the master breathes a little, round the mix's 0.85
  every 2 beats: master: filter lp 14k -> 3k + knob(3) * 6k over 1 beats exp   # (live) a half-bar pulse; the third knob sets how far it shuts
  master: delay 0.1 + knob(2) * 0.3                            # (live) and the second knob the delay send
  at bar 15 beat 3 for 1 beat: mix { A eq low -24 }            # drop-out before the breakdown
}

section hook_a half bars {
  bed(3)
  sparkle(8)
  deck B: melody <q1 q2 q3 q4> inst=pwm-lead vel=75..95
}

section hook_b half bars {
  bed(3)
  sparkle(16)
  deck B: melody <r1 r2 r3 r4> inst=pwm-lead vel=75..95
}

let drop = stack(groove, then(hook_a, hook_b))

section hush 4 bars {
  tempo base + 8 -> base - 18 over 2 bars log                  # the tempo falls away, then holds
  mix { A level 0.3, B level 0.55, master level 0.85 }
  deck A: hihat maybe(e(5,8), 0.75, 3) vel=30..50
  sub_long()
  bed(3)
  deck B: melody <s1 s2 s3 s4> inst=fm-bell vel=70..90
  deck B: sing "slow-ly the lan-terns float a-way" on melody voice=soprano   # (live) a control line: the render has no voice
  master: filter lp 9k -> 1500 over 2 bars                     # (live)
  master: reverb 0.5                                           # (live)
}

section lift 4 bars {
  tempo base - 18 -> base + 10 over 4 bars exp                 # and it winds back up into the second drop
  mix { B level 0.75, master level 0.85 }
  repeat 2 every 2 bars {
    at bar 0 for 2 bars: mix { A level 0.55 + $i * 0.25 }
  }
  deck A: kick e(4,16) vel=80..100 | hihat x*8 vel=40..70 | snare <~ ~ ~ x*16> vel=60..110
  sub_long()
  bed(3)
  sparkle(8)
  deck B: melody <t1 t2 t3 t4> inst=fm-bell vel=70..90
  deck B: sing "we car-ry all the light a-long" on melody voice=soprano   # (live)
  master: filter hp 100 -> 2500 over 4 bars exp                # (live)
}

let breakdown = then(hush, lift)

section groove2 drop_len bars {
  key bm                                                       # a tone up, said once: the hooks stack on this section, so they play in it too
  tempo base + 10
  mix {
    A level 0.9
    B level 0.85
    B eq low -6
    master level 0.85
  }
  drumline(3)
  sub_roll()
  duck B under A.kick 6db attack=5ms release=120ms
  master: filter off                                           # (live)
  master: reverb 0.15                                          # (live)
  master: level lfo sine 2 bars center=0.85 depth=0.03         # (live)
  repeat 4 every 4 bars {                                      # (live) a filter dip on the last two beats of every fourth bar
    at bar 3 beat 2 for 2 beats: master: filter lp 18k -> 900 over 2 beats exp
  }
  at bar 15 beat 2 for 2 beats: mix { A eq low -24 }           # the bass leaves two beats early before the outro
}

section hook2_a half bars {
  bed(3)
  sparkle(16)
  deck B: melody <q1 q2 q3 q4> inst=pwm-lead vel=75..95
}

section hook2_b half bars {
  bed(3)
  sparkle(16)
  deck B: melody <r1 r2 r3 r4> inst=pwm-lead vel=75..95
  deck B: sing "light it up and bring it home, the lan-terns one by one, we are the ones that glow, rise up and meet the sun" on melody key=bm voice=choir-aah   # (live) 25 syllables for the 25 notes of the answer phrase, sung twice
}

let drop2 = stack(groove2, then(hook2_a, hook2_b))

section outro 8 bars {
  tempo base + 10 -> base - 10 over 8 bars log                 # 132 down to 112
  mix { master level 0.85 }
  repeat 4 every 2 bars {                                      # and the fade is four steps down, each a mix held for two bars
    at bar 0 for 2 bars: mix { A level 0.4 - $i * 0.1, B level 0.5 - $i * 0.1 }
  }
  master: level 0.85 -> 0.3 over 8 bars log                    # (live) and the master falls away under them
  deck A: kick e(2,16) vel=60..80 | hihat/12 x ~ x x ~ x vel=30..50
  bed(3)
  sparkle(4)
  deck B: melody <s1 s2 s3 end_fall> inst=fm-bell vel=60..80
  deck B: sing "slow-ly the lan-terns float a-way" on melody bars=8 voice=soprano   # (live) the first line again, twice over
  master: filter lp 9k -> 400 over 8 bars                      # (live)
  master: reverb 0.3 -> 0.6 over 8 bars                        # (live)
}

arrange intro build drop breakdown drop2 outro
end after outro

# ---- what the program says about itself ----------------------------------------------------------------------------
assert ends
assert length == 2m ± 12s
assert key == am in intro
assert key == bm in hook2_a
assert level A < 2 * B in groove
assert level A < B in outro

#! btw 1
#! name: such stuff as dreams, 122
#! license: CC0-1.0
#! visibility: public
# such-stuff-as-dreams-122: a phrase compiled to a track (CC0-1.0; the words are Shakespeare's, The Tempest 4.1, first printed in
# 1623, in the public domain). `template(deep-house, @tempest_such_stuff)` is deep house at 122 in A minor whose vocal line is the
# verse: twenty syllables of iambic pentameter, each stressed one on a beat and accented, a four-bar line sung twice in every
# eight-bar section. In `night` the voice is buried (lower, darker, ducked under the kick); in `spot` it is up front, an octave
# up the first time and crossed onto the shaker's rhythm the second. The `drm_*` drums fill in a little more each pass; the kick
# and the clap stay put. Four passes, about four minutes. `btwd expand` writes it out as plain BeatScript to edit from there.
arrange from template(deep-house, @tempest_such_stuff)

# vocals: lyrics that read like code (CC0-1.0, an original track). docs/btw/phonemes.md
# Plain words go through the BeatScript lexicon; text between slashes is phonemes, sung exactly as written
# (`aa:` holds a syllable over the next note, `ay!` accents it); `@id` is a phrase of the phrasebook.
# In the browser a sing line is part of its deck's net: it plays through the deck's fader and the crossfader.
tempo 124
key am

deck A: kick x ~ x ~ | hihat ~ x ~ x vel=60..90 | bass a2 a2 e2 g2
deck B: melody <[a4 c5 e5 c5] [g4 b4 d5 b4]>

section call 8 bars {
  deck B: sing "we are the rave to-night" on melody voice=robot-choir
}

section answer 8 bars {
  deck B: sing "/w ee - aa: r - dh uh - r ay! v/ _ /h ie - er/" on melody voice=robot
}

section hands 8 bars {
  deck B: sing @hands_up on melody voice=android
  # the voice on deck B shapes deck A's bass and hats, as an insert on A (its fader and the crossfader take it)
  do vocoder set carrier=A modulator=B insert=true on=true mix=0 -> 1 over 8 bars
}

